"""Compare finite constructor terms/inductive signatures; not a proof of an endpoint."""
import re,json
from pathlib import Path
ROOT=Path.cwd()
COQ=ROOT/'lib/jeff-busy-beaver-zfc254/ZF/m254/coq/logic'
LEAN=ROOT/'Computability/BusyBeaver/Lean/BusyBeaver/ZFC'

def tokens(s):
    parts=re.findall(r'[A-Za-z_][A-Za-z_0-9]*|[0-9]+|[()+*]',s)
    assert re.sub(r'\s+','',''.join(parts))==re.sub(r'\s+','',s),s
    return parts
class Parse:
    def __init__(self,s,params):self.ts=tokens(s);self.i=0;self.ps={v:f'v{i}' for i,v in enumerate(params)}
    def atom(self):
        x=self.ts[self.i];self.i+=1
        if x=='(':
            a=self.add();assert self.ts[self.i]==')';self.i+=1;return a
        assert x not in [')','+','*'];return self.ps.get(x,x)
    def app(self):
        a=self.atom()
        while self.i<len(self.ts) and self.ts[self.i] not in [')','+','*']:a=['app',a,self.atom()]
        return a
    def mul(self):
        a=self.app()
        while self.i<len(self.ts) and self.ts[self.i]=='*':self.i+=1;a=['*',a,self.app()]
        return a
    def add(self):
        a=self.mul()
        while self.i<len(self.ts) and self.ts[self.i]=='+':self.i+=1;a=['+',a,self.mul()]
        return a
    def finish(self):
        a=self.add();assert self.i==len(self.ts),(self.ts,self.i);return a

def args(s):return re.findall(r'\b[A-Za-z_][A-Za-z_0-9]*\b',re.sub(r'\b(?:nat|Nat)\b','',s))
def body(s,name,coq):
    if coq:
        p=rf'\bDefinition {name}\b(.*?): nat :=\s*(.*?)\.'
        m=re.search(p,s,re.S);assert m,name
    else:
        p=rf'^def {name}\b([^\n]*?): Nat :=\s*(.*?)(?=\n(?:def |/--|--|inductive |theorem |end )|\Z)'
        m=re.search(p,s,re.M|re.S);assert m,name
    return args(m[1]),m[2].strip()
def constructor_types(s,coq):
    if coq:s=s.split('Inductive thm254 : nat -> Prop :=',1)[1].split('.',1)[0]
    else:s=s.split('inductive NumThm : Nat → Prop',1)[1].split('\ntheorem ',1)[0]
    out=[]
    for line in s.split('|')[1:]:
        header,typ=line.rsplit(':',1)
        header=header.strip(); name=header.split()[0]
        params=args(header[len(name):]);kind={'T_true':'truth','T_mp':'mp','T_gen':'gen','T_bundle':'bundle'}.get(name,re.sub(r'^T_r','rho',name))
        pieces=[]
        for p in typ.strip().replace('->','→').replace('<>','≠').split('→'):
            p=p.strip()
            if p.startswith('thm254 '):pieces.append(['N',Parse(p[len('thm254 '):],params).finish()])
            elif p.startswith('NumThm '):pieces.append(['N',Parse(p[len('NumThm '):],params).finish()])
            else:
                a,b=p.split('≠');pieces.append(['ne',Parse(a.strip(),params).finish(),Parse(b.strip(),params).finish()])
        out.append({'name':kind,'parameters':len(params),'signature':pieces})
    return out

def main():
    if not __debug__:raise RuntimeError('assertions required')
    c=(COQ/'Codes254.v').read_text();l=(LEAN/'Numeric254.lean').read_text()
    c=re.sub(r'\(\*.*?\*\)','',c,flags=re.S)
    names=['P','wim','wel','wal','weq','F','wn','wa','wex']+[f'rho{i}' for i in range(1,9)]+['bundleC','bundleG','bundle']
    terms=[]
    for n in names:
        ca,cb=body(c,n,True);la,lb=body(l,n,False)
        assert len(ca)==len(la),(n,ca,la)
        cc=Parse(cb,ca).finish();lc=Parse(lb,la).finish();assert cc==lc,n
        terms.append({'name':n,'parameters':len(ca),'normalized_term':cc})
    assert 'match n with 0 => 0 | S m => S m + tri m end' in c
    assert 'def tri : Nat → Nat\n  | 0 => 0\n  | n + 1 => n + 1 + tri n' in l
    cs=constructor_types((COQ/'Thm254.v').read_text(),True);ls=constructor_types(l,False)
    assert len(cs)==len(ls)==12
    assert cs==ls,(cs,ls)
    enum=(COQ/'Enum254.v').read_text()
    assert 'if Nat.eqb c a || Nat.eqb c b then 0 else bundle a b c' in enum
    assert 'if c == a || c == b then 0 else bundle a b c' in l
    result={'all_twenty_nonrecursive_numeric_definitions_match':True,'terms':terms,'triangle_recursion_matches':True,'all_twelve_constructor_signatures_match':True,'constructors':cs,'gate_uses_same_two_Nat_equality_tests_and_zero_failure_value':True,'scope':'Syntactic finite-definition comparison, modulo binder alpha-renaming and standard Nat equality-test notation. No endpoint or semantic calibration is proved.'}
    p=Path(__file__).with_name('source-contract.json');p.write_text(json.dumps(result,indent=2)+'\n')
    print(json.dumps({k:v for k,v in result.items() if k not in ['terms','constructors']}))
if __name__=='__main__':main()
